(function() {
    'use strict';

    class PortMasterAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'PortMaster: Port & Maritime Logistics';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    theme: 'operational',
                    panelId: 'round1Panel',
                    description: '<b>Year 1 — Operational Efficiency & Cost Management</b><br><br>Puerto Libertad is profitable ($100M/year) but losing market share. Dwell time is 11 days (competitors: 6-8 days). Vessel turnaround is 4 days (best practice: 1-2 days).<br><br>Your $200M capital budget must be deployed wisely over 3 years. This year, focus on operational foundations: IT systems for cargo tracking, customs facilitation, crane strategy, and labor model.<br><br>Every day of dwell time reduction increases shipper satisfaction 2-3% and volume 1-2%. Efficiency is your fastest competitive weapon.',
                    event: null
                },
                {
                    theme: 'capital',
                    panelId: 'round2Panel',
                    description: '<b>Year 2 — Capital Investment & Expansion</b><br><br>Your efficiency investments are showing results. Now decide on major capital projects: berth expansion to handle growing demand, hinterland connectivity to unlock interior markets, and terminal specialization to capture higher-margin cargo.<br><br>Puerto Eficiente (your main rival) has announced a 20% crane upgrade program. They are closing the efficiency gap. You must decide whether to expand capacity or deepen efficiency advantages.',
                    event: null
                },
                {
                    theme: 'strategic',
                    panelId: 'round3Panel',
                    description: '<b>Year 3 — Strategic Partnerships & Sustainability</b><br><br>The port has transformed operationally. Now position for the long term: pursue transshipment hub status to capture transit cargo, negotiate shipping line alliances for guaranteed volume, invest in green infrastructure to attract ESG-conscious carriers, and decide on climate resilience spending.<br><br>A Category 3 hurricane has a 25% chance of hitting the coast this year. Ports without protection face 20-30% business interruption.',
                    event: null
                }
            ];

            this.EVENTS = [
                [
                    {title: 'Trade Agreement', text: 'New trade deal between Maravella and China increases import forecast 30% over 2 years. Opportunity if you have capacity and efficiency.'},
                    {title: 'Shipping Line Consolidation', text: 'Maersk and MSC announce merger talks. The combined entity will have massive negotiating power over port fees.'},
                    {title: 'Labor Strike Threat', text: 'The port union warns of strike action if workforce reductions proceed. Social stability is at risk.'}
                ],
                [
                    {title: 'Maersk Volume Commitment', text: 'Maersk offers 200K TEU/year commitment if you maintain sub-6 day dwell time. Huge revenue opportunity.'},
                    {title: 'Climate Risk Alert', text: 'Hurricane forecast models show 25% probability of Category 3+ hurricane in the next 2 years. Coastal infrastructure at risk.'},
                    {title: 'Economic Slowdown', text: 'Maravella GDP growth revised down from 4% to 1.5%. Cargo forecasts reduced 20%. Capex ROI calculations need revision.'}
                ],
                [
                    {title: 'Rail Completion', text: 'Government confirms rail connection will complete on schedule! Interior cargo access is now 40% cheaper. Port volume forecasted to grow 50% over 5 years.'},
                    {title: 'Hurricane Hits Coast', text: 'Category 3 hurricane struck the coast! Ports without seawall protection suffered 30% downtime and $50M in damage. Protected ports: minimal impact.'},
                    {title: 'Green Shipping Mandate', text: 'IMO announces accelerated 2045 decarbonization targets. Ports with shore power and green incentives gain immediate preference from major carriers.'}
                ]
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    throughput: 800000,
                    dwellTime: 11.0,
                    turnaroundTime: 4.0,
                    revenue: 320,
                    operatingCosts: 220,
                    profit: 100,
                    capitalBudget: 200,
                    totalDebt: 0,
                    marketShare: 12.0,
                    satisfaction: 60,
                    berths: 8,
                    craneAge: 17,
                    laborCost: 120,
                    hasRail: false,
                    hasDepot: false,
                    hasShorepower: false,
                    hasSeawall: false,
                    greenScore: 0,
                    sustainabilityScore: 0,
                    cumulativeProfit: 0,
                    competitorDwell: 8,
                    competitorThroughput: 780000,
                    eventIndex: -1,
                    hurricaneHit: false,
                    railCompleted: false,
                    throughputHistory: [],
                    profitHistory: [],
                    dwellHistory: [],
                    marketShareHistory: [],
                    revenueHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    itInvest: 10,
                    customsInvest: 5,
                    craneStrategy: 'maintenance',
                    laborModel: 'status_quo',
                    berthExpansion: 'none',
                    hinterland: 'roads',
                    specialization: 'general',
                    transshipment: 0,
                    shippingContract: 'short',
                    greenInfra: 'none',
                    resilience: 'none'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var round = Math.min((state.currentPeriod || 1) - 1, 2);
            var ds = state.domainState;
            var spent = 0;

            if (round === 0) {
                var itInput = document.getElementById('itInvestInput');
                if (itInput) decisions.itInvest = parseFloat(itInput.value) || 0;
                var custInput = document.getElementById('customsInvestInput');
                if (custInput) decisions.customsInvest = parseFloat(custInput.value) || 0;
                var craneInput = document.getElementById('craneStrategyInput');
                if (craneInput) decisions.craneStrategy = craneInput.value;
                var laborInput = document.getElementById('laborModelInput');
                if (laborInput) decisions.laborModel = laborInput.value;

                spent = decisions.itInvest + decisions.customsInvest;
                if (decisions.craneStrategy === 'maintenance') spent += 30;
                else if (decisions.craneStrategy === 'selective') spent += 80;
                else if (decisions.craneStrategy === 'full') spent += 280;

                if (decisions.itInvest < 0 || decisions.itInvest > 20) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('it_warning'), 'warning');
                    return false;
                }
                if (decisions.customsInvest < 0 || decisions.customsInvest > 15) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('customs_warning'), 'warning');
                    return false;
                }
            } else if (round === 1) {
                var berthInput = document.getElementById('berthInput');
                if (berthInput) decisions.berthExpansion = berthInput.value;
                var hintInput = document.getElementById('hinterlandInput');
                if (hintInput) decisions.hinterland = hintInput.value;
                var specInput = document.getElementById('specializationInput');
                if (specInput) decisions.specialization = specInput.value;

                if (decisions.berthExpansion === 'micro') spent += 80;
                else if (decisions.berthExpansion === 'full') spent += 0;

                if (decisions.hinterland === 'roads') spent += 10;
                else if (decisions.hinterland === 'depot') spent += 40;
                else if (decisions.hinterland === 'rail') spent += 50;
                else if (decisions.hinterland === 'depot_rail') spent += 90;

                if (decisions.specialization === 'reefer') spent += 30;
                else if (decisions.specialization === 'roro') spent += 40;
                else if (decisions.specialization === 'breakbulk') spent += 20;
            } else {
                var transInput = document.getElementById('transshipmentInput');
                if (transInput) decisions.transshipment = parseFloat(transInput.value) || 0;
                var shipInput = document.getElementById('shippingContractInput');
                if (shipInput) decisions.shippingContract = shipInput.value;
                var greenInput = document.getElementById('greenInput');
                if (greenInput) decisions.greenInfra = greenInput.value;
                var resInput = document.getElementById('resilienceInput');
                if (resInput) decisions.resilience = resInput.value;

                spent = decisions.transshipment;
                if (decisions.shippingContract === 'premium') spent += 15;
                if (decisions.greenInfra === 'shore_power') spent += 25;
                else if (decisions.greenInfra === 'discount') spent += 5;
                else if (decisions.greenInfra === 'both') spent += 30;
                if (decisions.resilience === 'partial') spent += 50;
                else if (decisions.resilience === 'full') spent += 100;

                if (decisions.transshipment < 0 || decisions.transshipment > 30) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('transshipment_warning'), 'warning');
                    return false;
                }
            }

            // Full berth expansion is debt-financed, so its cost is intentionally excluded
            // from `spent` above (it adds $300M debt, not cash). All OTHER cash spend in the
            // round must still be checked against the capital budget, so the check runs
            // unconditionally -- the previous `&& berthExpansion !== 'full'` clause wrongly
            // disabled the ENTIRE cash check whenever full berth was chosen. (fix v1.1.0)
            if (spent > ds.capitalBudget) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_exceeded'), 'warning');
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = Math.min((state.currentPeriod || 1) - 1, 2);
            var spent = 0;
            var dwellReduction = 0;
            var turnaroundReduction = 0;
            var throughputMultiplier = 1.0;
            var revenueBonus = 0;
            var costChange = 0;
            var satisfactionChange = 0;
            var marketShareChange = 0;
            var greenPoints = 0;
            var debtAdded = 0;

            var evtIdx = Math.floor(Math.random() * 3);
            ds.eventIndex = evtIdx;

            if (round === 0) {
                var itEffect = Math.min(d.itInvest / 20, 1.0);
                dwellReduction = itEffect * 2.5;

                var customsEffect = Math.min(d.customsInvest / 15, 1.0);
                dwellReduction += customsEffect * 2.0;

                if (d.craneStrategy === 'maintenance') {
                    spent += 30;
                    turnaroundReduction = 0.3;
                    throughputMultiplier = 1.0;
                } else if (d.craneStrategy === 'selective') {
                    spent += 80;
                    turnaroundReduction = 0.8;
                    throughputMultiplier = 1.15;
                } else if (d.craneStrategy === 'full') {
                    spent += 280;
                    turnaroundReduction = 1.5;
                    throughputMultiplier = 1.30;
                }

                spent += d.itInvest + d.customsInvest;

                if (d.laborModel === 'status_quo') {
                    costChange = 0;
                    satisfactionChange = 0;
                } else if (d.laborModel === 'efficiency') {
                    costChange = -25;
                    dwellReduction += 1.0;
                    var strikeRoll = Math.random();
                    if (strikeRoll < 0.3) {
                        satisfactionChange = -10;
                        throughputMultiplier *= 0.92;
                        ds.eventIndex = 2;
                    } else {
                        satisfactionChange = 3;
                    }
                } else if (d.laborModel === 'automation') {
                    costChange = -15;
                    dwellReduction += 0.5;
                    satisfactionChange = 2;
                }

                if (evtIdx === 0 && ds.eventIndex !== 2) {
                    throughputMultiplier *= 1.08;
                } else if (evtIdx === 1 && ds.eventIndex !== 2) {
                    satisfactionChange -= 3;
                }

                satisfactionChange += dwellReduction * 2.5;
                marketShareChange = dwellReduction * 0.3;

            } else if (round === 1) {
                if (d.berthExpansion === 'none') {
                    spent += 0;
                } else if (d.berthExpansion === 'micro') {
                    spent += 80;
                    ds.berths = 9;
                    throughputMultiplier = 1.08;
                    revenueBonus = 15;
                    turnaroundReduction = 0.3;
                } else if (d.berthExpansion === 'full') {
                    debtAdded = 300;
                    ds.berths = 10;
                    throughputMultiplier = 1.25;
                    revenueBonus = 30;
                    turnaroundReduction = 0.5;
                }

                if (d.hinterland === 'roads') {
                    spent += 10;
                    throughputMultiplier *= 1.03;
                    satisfactionChange += 3;
                } else if (d.hinterland === 'depot') {
                    spent += 40;
                    ds.hasDepot = true;
                    throughputMultiplier *= 1.08;
                    dwellReduction = 1.5;
                    satisfactionChange += 6;
                } else if (d.hinterland === 'rail') {
                    spent += 50;
                    ds.hasRail = true;
                    throughputMultiplier *= 1.05;
                    satisfactionChange += 4;
                } else if (d.hinterland === 'depot_rail') {
                    spent += 90;
                    ds.hasDepot = true;
                    ds.hasRail = true;
                    throughputMultiplier *= 1.12;
                    dwellReduction = 1.5;
                    satisfactionChange += 10;
                }

                if (d.specialization === 'reefer') {
                    spent += 30;
                    revenueBonus += 20;
                    satisfactionChange += 4;
                } else if (d.specialization === 'roro') {
                    spent += 40;
                    revenueBonus += 15;
                    throughputMultiplier *= 1.04;
                } else if (d.specialization === 'breakbulk') {
                    spent += 20;
                    revenueBonus += 10;
                    throughputMultiplier *= 0.98;
                }

                if (evtIdx === 0) {
                    satisfactionChange += 8;
                    revenueBonus += 10;
                } else if (evtIdx === 1) {
                    satisfactionChange -= 5;
                } else if (evtIdx === 2) {
                    throughputMultiplier *= 0.93;
                    revenueBonus -= 10;
                }

                ds.competitorDwell = Math.max(5.5, ds.competitorDwell - 1.5);
                ds.competitorThroughput = Math.round(ds.competitorThroughput * 1.09);
                marketShareChange = (ds.throughput * throughputMultiplier - ds.competitorThroughput) / 100000;

            } else {
                spent = d.transshipment;
                var transEffect = Math.min(d.transshipment / 30, 1.0);
                throughputMultiplier = 1.0 + transEffect * 0.12;
                revenueBonus = transEffect * 25;

                if (d.shippingContract === 'short') {
                    satisfactionChange += 2;
                } else if (d.shippingContract === 'long') {
                    throughputMultiplier *= 1.08;
                    revenueBonus += 15;
                    satisfactionChange += 6;
                } else if (d.shippingContract === 'premium') {
                    spent += 15;
                    revenueBonus += 25;
                    throughputMultiplier *= 1.05;
                    satisfactionChange += 10;
                }

                if (d.greenInfra === 'shore_power') {
                    spent += 25;
                    ds.hasShorepower = true;
                    greenPoints = 40;
                    satisfactionChange += 5;
                } else if (d.greenInfra === 'discount') {
                    spent += 5;
                    greenPoints = 20;
                    revenueBonus -= 5;
                    satisfactionChange += 3;
                } else if (d.greenInfra === 'both') {
                    spent += 30;
                    ds.hasShorepower = true;
                    greenPoints = 60;
                    revenueBonus -= 3;
                    satisfactionChange += 8;
                }

                if (d.resilience === 'partial') {
                    spent += 50;
                    ds.hasSeawall = true;
                    greenPoints += 15;
                } else if (d.resilience === 'full') {
                    spent += 100;
                    ds.hasSeawall = true;
                    greenPoints += 30;
                }

                var hurricaneRoll = Math.random();
                if (hurricaneRoll < 0.30) {
                    ds.hurricaneHit = true;
                    ds.eventIndex = 1;
                    if (!ds.hasSeawall) {
                        throughputMultiplier *= 0.70;
                        revenueBonus -= 50;
                        costChange += 50;
                        satisfactionChange -= 20;
                    } else if (d.resilience === 'partial') {
                        throughputMultiplier *= 0.90;
                        revenueBonus -= 10;
                        satisfactionChange -= 5;
                    } else {
                        throughputMultiplier *= 0.97;
                        satisfactionChange += 5;
                    }
                } else {
                    if (ds.hasRail && evtIdx === 0) {
                        ds.railCompleted = true;
                        ds.eventIndex = 0;
                        throughputMultiplier *= 1.20;
                        revenueBonus += 30;
                        satisfactionChange += 12;
                    } else if (evtIdx === 2) {
                        if (ds.hasShorepower) {
                            satisfactionChange += 10;
                            revenueBonus += 10;
                        }
                    }
                }

                ds.competitorDwell = Math.max(5.0, ds.competitorDwell - 0.5);
                ds.competitorThroughput = Math.round(ds.competitorThroughput * 1.06);
                marketShareChange = (ds.throughput * throughputMultiplier - ds.competitorThroughput) / 80000;
            }

            ds.capitalBudget = Math.max(0, ds.capitalBudget - spent);
            ds.totalDebt += debtAdded;

            ds.dwellTime = Math.max(3.0, ds.dwellTime - dwellReduction);
            ds.turnaroundTime = Math.max(1.2, ds.turnaroundTime - turnaroundReduction);

            var baseGrowth = 1.03;
            var efficiencyLift = 1.0 + Math.max(0, 11 - ds.dwellTime) * 0.005;
            ds.throughput = Math.round(ds.throughput * baseGrowth * efficiencyLift * throughputMultiplier);

            // Revenue calibrated (v1.1.0) so the opening state (800K TEU, 11-day dwell,
            // status-quo costs) reconciles with the displayed baseline of ~$320M revenue /
            // ~$100M profit stated in the briefing. Previously the handling coefficient of
            // 0.25 produced only ~$212M base revenue, so a sensible first year swung the port
            // to a LOSS -- contradicting the "profitable, losing market share" premise. The
            // coefficient (0.385) keeps revenue monotonic in throughput.
            var handlingRevenue = (ds.throughput / 1000) * 0.385;
            var vesselRevenue = (ds.throughput / 1100) * 0.008;
            var storageRevenue = (ds.throughput / 1000) * (ds.dwellTime / 365) * 0.05;
            ds.revenue = Math.round(handlingRevenue + vesselRevenue + storageRevenue + revenueBonus + 5);

            ds.laborCost = Math.max(70, ds.laborCost + costChange);
            var maintenance = ds.craneAge > 10 ? 45 : 30;
            if (round === 0) {
                if (d.craneStrategy === 'selective') { ds.craneAge = 5; maintenance = 25; }
                else if (d.craneStrategy === 'full') { ds.craneAge = 1; maintenance = 15; }
                else { ds.craneAge += 1; }
            }
            // Fixed non-labor operating cost reduced from +60 to +25 so baseline opex (~$220M)
            // matches the briefing figure and baseline profit lands near the displayed $100M. (v1.1.0)
            ds.operatingCosts = Math.round(ds.laborCost + maintenance + 25);
            var debtInterest = Math.round(ds.totalDebt * 0.05);
            var depreciation = 30;

            ds.profit = Math.round(ds.revenue - ds.operatingCosts - debtInterest - depreciation);
            ds.cumulativeProfit += ds.profit;

            ds.satisfaction = Math.max(0, Math.min(100, ds.satisfaction + satisfactionChange));
            ds.marketShare = Math.max(5, Math.min(25, ds.marketShare + marketShareChange));
            ds.greenScore += greenPoints;
            ds.sustainabilityScore = Math.min(100, ds.greenScore + (ds.hasSeawall ? 20 : 0) + (ds.hasShorepower ? 15 : 0));

            if (!ds.revenueHistory) ds.revenueHistory = [];  // backward-compat for resumed saves
            ds.throughputHistory.push(ds.throughput);
            ds.profitHistory.push(ds.profit);
            ds.dwellHistory.push(ds.dwellTime);
            ds.marketShareHistory.push(ds.marketShare);
            ds.revenueHistory.push(ds.revenue);

            var results = {
                period: state.currentPeriod,
                throughput: ds.throughput,
                dwellTime: ds.dwellTime,
                turnaroundTime: ds.turnaroundTime,
                revenue: ds.revenue,
                profit: ds.profit,
                marketShare: ds.marketShare,
                satisfaction: ds.satisfaction,
                capitalSpent: spent,
                budgetRemaining: ds.capitalBudget,
                sustainabilityScore: ds.sustainabilityScore,
                greenScore: ds.greenScore
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('throughputDisplay', 'domainState.throughput', function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('dwellDisplay', 'domainState.dwellTime', function(v) { return v.toFixed(1); });
            uiManager.bind('turnaroundDisplay', 'domainState.turnaroundTime', function(v) { return v.toFixed(1); });
            uiManager.bind('revenueDisplay', 'domainState.revenue', function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('profitDisplay', 'domainState.profit', function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('budgetDisplay', 'domainState.capitalBudget', function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('marketShareDisplay', 'domainState.marketShare', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('satisfactionDisplay', 'domainState.satisfaction', function(v) { return Math.round(v) + '%'; });
        }

        getChartConfig() {
            return {
                performanceChart: {
                    type: 'line',
