        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.results || {};
            var finalThroughput = ds.throughput || 800000;
            var finalDwell = ds.dwellTime || 11;
            var finalTurnaround = ds.turnaroundTime || 4;
            var totalProfit = 0;
            for (var i = 0; i < history.length; i++) {
                totalProfit += (history[i].results && history[i].results.profit) || 0;
            }
            var finalMarketShare = ds.marketShare || 12;
            var finalSatisfaction = ds.satisfaction || 60;
            var finalSustain = ds.sustainabilityScore || 0;

            // Weights (v1.1.0): throughput 25, efficiency 25, financial 20, share 15, sustainability 15 = 100.
            // Previously sustainability was a hardcoded flat 5, so Round 3's entire theme (green
            // infrastructure, climate resilience) had NO effect on the final score. It now reads
            // the actual sustainabilityScore the player built. Financial denominator raised to 480
            // to match the recalibrated (higher) revenue base so it still discriminates. (v1.1.0)
            var throughputScore = Math.min(1, finalThroughput / 1200000) * 25;
            var efficiencyScore = Math.min(1, (11 - finalDwell) / 6 * 0.5 + (4 - finalTurnaround) / 2.8 * 0.5) * 25;
            var financialScore = Math.min(1, totalProfit / 480) * 20;
            var shareScore = Math.min(1, finalMarketShare / 20) * 15;
            var sustainScore = Math.min(1, finalSustain / 100) * 15;
            var total = Math.round(throughputScore + efficiencyScore + financialScore + shareScore + sustainScore);

            var performance = 'Developing Port';
            if (total >= 80) performance = 'World-Class Port Authority';
            else if (total >= 65) performance = 'Competitive Regional Hub';
            else if (total >= 50) performance = 'Improving Port';

            var insights = [];
            if (finalDwell <= 5) insights.push('Excellent dwell time reduction drove shipper satisfaction and volume growth.');
            else if (finalDwell <= 7) insights.push('Good operational improvement. Further dwell time reduction would unlock more growth.');
            else insights.push('Dwell time remained high. Operational efficiency should have been the top priority.');

            if (totalProfit > 300) insights.push('Strong financial performance with sustainable profitability.');
            else if (totalProfit > 200) insights.push('Solid financial results. Capital discipline was maintained.');
            else insights.push('Profitability was strained. Review capital allocation for better ROI.');

            if (finalMarketShare > 16) insights.push('Market share gains demonstrate competitive positioning success.');
            else insights.push('Market share gains were modest. Competitor ports kept pace.');

            if (finalSustain >= 60) insights.push('Strong sustainability posture (green infrastructure and climate resilience) positions the port for ESG-driven carrier demand and long-term license to operate.');
            else if (finalSustain >= 30) insights.push('Some sustainability investment was made, but green infrastructure and resilience could be deepened to attract ESG-conscious carriers.');
            else insights.push('Sustainability was neglected. Green infrastructure and climate resilience are increasingly decisive for major carriers and regulators.');

            return {
                totalScore: total,
                throughputFinal: finalThroughput,
                dwellTimeFinal: finalDwell,
                totalProfit: totalProfit,
                marketShareFinal: finalMarketShare,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.profit < 50) return window.mySimulation.t('hint_low_profit');
            if (results.dwellTime > 8) return window.mySimulation.t('hint_high_dwell');
            if (results.satisfaction < 50) return window.mySimulation.t('hint_low_satisfaction');
            if (results.marketShare < 10) return window.mySimulation.t('hint_losing_share');
            return null;
