        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.description;

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? '' : 'none';
            }

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            var ds = state.domainState;
            if (ds && ds.eventIndex >= 0 && state.currentPeriod > 1) {
                var prevRound = Math.min((state.currentPeriod || 1) - 2, 2);
                var evt = this.EVENTS[prevRound][ds.eventIndex];
                if (eventPanel && eventText && evt) {
                    eventPanel.style.display = 'block';
                    eventText.innerHTML = '<b>' + evt.title + ':</b> ' + evt.text;
                }
            } else {
                if (eventPanel) eventPanel.style.display = 'none';
            }
        }
